#!/usr/bin/env bash
set -euo pipefail
# Ensure verification compiles with the same settings as deployment.
export FOUNDRY_PROFILE="${FOUNDRY_PROFILE:-default}"
ETHERSCAN_API_KEY="${ETHERSCAN_API_KEY:-${ETHERSCAN_V2_API_KEY:-}}"
if [ -z "$ETHERSCAN_API_KEY" ]; then echo "set ETHERSCAN_API_KEY (or ETHERSCAN_V2_API_KEY)"; exit 1; fi
CHAIN_ID=84532
VERIFIER_URL="${VERIFIER_URL:-https://api.etherscan.io/v2/api?chainid=84532}"

# Foundry uses --chain (docs) but some older builds accepted --chain-id.
CHAIN_FLAG="--chain"
if forge verify-contract --help 2>/dev/null | grep -q -- "--chain-id"; then CHAIN_FLAG="--chain-id"; fi

PROFILE_FLAG=""
if forge verify-contract --help 2>/dev/null | grep -q -- "--compilation-profile"; then PROFILE_FLAG="--compilation-profile default"; fi

forge verify-contract 0xE0d106dB20363D9aB39FE1DC547A7d5052020120 src/adapters/chainlink/ChainlinkV2PlusWrapperAdapter.sol:ChainlinkV2PlusWrapperAdapter $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x0000000000000000000000007a1bac17ccc5b313516c5e16fb24f7659aa5ebed000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x3e80e96B8f6F9C5b1d48037Ba1c020642E22A5A9 src/core/VRFHub.sol:VRFHub $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000e0d106db20363d9ab39fe1dc547a7d5052020120000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x7658219104a3b7d1966Fe1bACc305aa869387146 src/core/PoolRegistry.sol:PoolRegistry $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x1C8560a4f2584d9A6Bbbe6647a91F0221092C179 src/core/SettlementRouter.sol:SettlementRouter $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x0000000000000000000000007658219104a3b7d1966fe1bacc305aa869387146
forge verify-contract 0x072078aB8b73Ff1dcb10Fe37775be733FC2af499 src/engines/referral/ReferralRegistry.sol:ReferralRegistry $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x19c0C646c6ca01075657c35382BF20185FCcE568 src/engines/referral/DefaultReferralEngine.sol:DefaultReferralEngine $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x7Bba34F0ac9476b856026273ef66dfC4Da33B102 src/core/GameHub.sol:GameHub $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0x9a6B13b7C3b54aDbEE57A37293978dFBFF7237c9 src/core/Bank.sol:Bank $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0x0ec066C81Eb3866b32Aa59724dd49fa263d7CB17 src/core/Bank.sol:Bank $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0xCE46a976eEA806982Ea8b70D7706DEFbDc69a07E src/modules/dice/DiceModule.sol:DiceModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xaac9d2478E178bC5d936b69624482d91BA07B463 src/modules/cointoss/CoinTossModule.sol:CoinTossModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x858Acea7229298b48286f2b3B17C9F5589375D70 src/modules/roulette/RouletteModule.sol:RouletteModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xebE5A01890b36869B8137e50Fc5a68f88e176Bd6 src/modules/keno/KenoModule.sol:KenoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xC8AC93105085228cf933Eb9136A0ef4AD3325c1E src/modules/plinko/PlinkoModule.sol:PlinkoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xfC7Ab37Af06eDE7d0a4F56d2d75acCb534739e2D src/modules/sicbo/SicBoModule.sol:SicBoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xC153Cab8A0899497524449e22bD85CD368884284 src/modules/slots/SlotsModule.sol:SlotsModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xC5B33221016a12c6b61D9d8BBdB07c2E70c1b4Dd src/modules/baccarat/BaccaratModule.sol:BaccaratModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
